// Catalog entry - one per title
record Book(String isbn, String title, String author, String genre) {
    private final List<BookItem> copies = new ArrayList<>();

    public void addCopy(BookItem item) {
        copies.add(item);
    }

    public Optional<BookItem> findAvailableCopy() {
        return copies.stream()
            .filter(item -> item.status() == ItemStatus.AVAILABLE)
            .findFirst();
    }
}

// Physical copy - many per book
record BookItem(String barcode, Book book, String shelfLocation, ItemStatus status) {}

enum ItemStatus { AVAILABLE, LOANED, RESERVED, LOST }

// Transaction linking member to physical copy
record BookLending(Long id, Member member, BookItem item, 
                   LocalDate issueDate, LocalDate dueDate, LocalDate returnDate) {

    public boolean isOverdue() {
        return returnDate == null && LocalDate.now().isAfter(dueDate);
    }
}

record Member(Long id, String name, String email, List<BookLending> activeLoans) {}

record Reservation(Long id, Member member, Book book, LocalDate createdDate) {}

