interface BookObserver {
    void onBookItemReturned(BookItem item);
}

class Book implements BookObserver {
    private final String isbn;
    private final Queue<Reservation> reservationQueue = new LinkedList<>();
    private final List<BookItem> copies = new ArrayList<>();

    public void reserve(Member member) {
        if (hasAvailableCopy()) {
            throw new IllegalStateException("Book available, no reservation needed");
        }
        var reservation = new Reservation(member, this, LocalDateTime.now());
        reservationQueue.offer(reservation); // FIFO order
    }

    @Override
    public void onBookItemReturned(BookItem item) {
        Reservation next = reservationQueue.peek();
        if (next != null && !next.isExpired()) {
            notifyMember(next.member(), "Your reserved book is ready");
            next.setNotifiedAt(LocalDateTime.now());
        }
    }

    private boolean hasAvailableCopy() {
        return copies.stream().anyMatch(item -> item.isAvailable());
    }
}

class BookItem {
    private Book book;
    private ItemStatus status;

    public void returnBook() {
        this.status = ItemStatus.AVAILABLE;
        book.onBookItemReturned(this); // Notify observer
    }
}

record Reservation(Member member, Book book, LocalDateTime createdAt, LocalDateTime notifiedAt) {
    boolean isExpired() {
        return notifiedAt != null && 
               Duration.between(notifiedAt, LocalDateTime.now()).toHours() > 24;
    }
}

