interface SearchCriteria {
    List<Book> execute(Collection<Book> catalog);
}

class SearchByTitle implements SearchCriteria {
    private final String title;

    public SearchByTitle(String title) {
        this.title = title.toLowerCase();
    }

    @Override
    public List<Book> execute(Collection<Book> catalog) {
        return catalog.stream()
            .filter(book -> book.title().toLowerCase().contains(title))
            .toList();
    }
}

class SearchByAuthor implements SearchCriteria {
    private final String author;

    public SearchByAuthor(String author) {
        this.author = author.toLowerCase();
    }

    @Override
    public List<Book> execute(Collection<Book> catalog) {
        return catalog.stream()
            .filter(book -> book.author().toLowerCase().contains(author))
            .toList();
    }
}

class SearchByISBN implements SearchCriteria {
    private final String isbn;

    public SearchByISBN(String isbn) { this.isbn = isbn; }

    @Override
    public List<Book> execute(Collection<Book> catalog) {
        return catalog.stream()
            .filter(book -> book.isbn().equals(isbn))
            .limit(1) // ISBN is unique
            .toList();
    }
}

class LibraryCatalog {
    private final List<Book> books = new ArrayList<>();

    public List<Book> search(SearchCriteria criteria) {
        return criteria.execute(books); // Delegate to strategy
    }
}

// Usage
var catalog = new LibraryCatalog();
var results = catalog.search(new SearchByAuthor("Martin Fowler"));

