interface FineCalculator {
    BigDecimal calculate(BookLending lending, LocalDate returnDate);
}

class StandardFineCalculator implements FineCalculator {
    private static final BigDecimal DAILY_RATE = new BigDecimal("1.00");
    private static final int GRACE_DAYS = 1;

    @Override
    public BigDecimal calculate(BookLending lending, LocalDate returnDate) {
        long overdueDays = ChronoUnit.DAYS.between(lending.dueDate(), returnDate);

        if (overdueDays <= GRACE_DAYS) {
            return BigDecimal.ZERO; // Grace period
        }

        long chargeableDays = overdueDays - GRACE_DAYS;
        return DAILY_RATE.multiply(BigDecimal.valueOf(chargeableDays));
    }
}

class ProgressiveFineCalculator implements FineCalculator {
    @Override
    public BigDecimal calculate(BookLending lending, LocalDate returnDate) {
        long overdueDays = ChronoUnit.DAYS.between(lending.dueDate(), returnDate);
        if (overdueDays <= 0) return BigDecimal.ZERO;

        // First 7 days: $1/day, after that: $2/day
        long firstWeekDays = Math.min(overdueDays, 7);
        long remainingDays = Math.max(0, overdueDays - 7);

        var firstWeekFine = new BigDecimal("1.00").multiply(BigDecimal.valueOf(firstWeekDays));
        var additionalFine = new BigDecimal("2.00").multiply(BigDecimal.valueOf(remainingDays));

        return firstWeekFine.add(additionalFine);
    }
}

class Member {
    private BigDecimal outstandingFines = BigDecimal.ZERO;

    public void addFine(BigDecimal amount) {
        outstandingFines = outstandingFines.add(amount);
    }

    public boolean canBorrow() {
        return outstandingFines.compareTo(BigDecimal.ZERO) == 0; // No outstanding fines
    }
}

